NEW_FILES = {'tests/unit/test_the_enemy_sights_from_the_contract.py': '"""The enemy sights from the contract\'s body too (the factory\'s roadmap 292).\n\n`adapters/laser_tag` writes the contract\'s body into every run\'s scenario\n(roadmap 123), and until 0.231.0 it wrote only the player\'s: the scenario\'s\n`enemy_eye_height_m` went out at `_STOCK_SCENARIO`\'s 1.6 whatever the contract\nsaid. The contract says its NPCs share the player\'s metrics until a distinct\nclass ships, and Laser Tag has built every enemy\'s capsule, mesh and agent from\nthe crew\'s body since its 0.26.0 -- so a studio stating a 2.05 m character\nfielded 2.05 m enemies sighting from 1.6 m, and the evaluator\'s lines crossed\nat 1.42 m where the body\'s own cross at 1.5.\n\nThe enemy\'s eye is `characters.npc_standard`\'s now, and the player\'s where that\nblock states none.\n\nTHE TEST THAT MATTERS IS `test_a_studio_states_its_body_once_and_both_sides_take_it`.\n"""\nimport json\nfrom pathlib import Path\n\nimport pytest\n\nfrom adapters import laser_tag\nfrom packages.validation import agent_contract, lasertag_contract\nfrom tests.siblings import not_found, sibling_repo\n\n#: A 2.05 m character: the eye at 0.9 of stature, the chest inside the capsule.\nTALL = {"radius_m": 0.45, "height_m": 2.05, "eye_height_m": 1.85,\n        "chest_height_m": 1.15, "walk_speed_mps": 3.2}\n\n\ndef _contract(root: Path, npc: dict | None = None, **player) -> Path:\n    body = {"radius_m": 0.35, "height_m": 1.8, "eye_height_m": 1.6,\n            "chest_height_m": 1.0, "walk_speed_mps": 4.0}\n    body.update(player)\n    characters = {"player": body}\n    if npc is not None:\n        characters["npc_standard"] = npc\n    root.mkdir(parents=True, exist_ok=True)\n    (root / "agent_contract.json").write_text(\n        json.dumps({"characters": characters}), encoding="utf-8")\n    return root\n\n\ndef _staged(root: Path) -> Path:\n    """A project with the addon script present, which `_write_scenario` requires."""\n    script = root / "addons" / "laser_tag_tool" / "resources"\n    script.mkdir(parents=True)\n    (script / "LT_TestScenario.gd").write_text("# stub", encoding="utf-8")\n    return root\n\n\ndef test_a_studio_states_its_body_once_and_both_sides_take_it(tmp_path):\n    """THE POINT OF THE ITEM. One stated body and an NPC stating nothing of its\n    own: the crew and the enemy both sight from 1.85 m, in the scenario the run\n    writes and in the engagement the advisory is handed, and the evaluator\'s\n    lines cross where the body\'s own do."""\n    dc = _contract(tmp_path / "dc", npc={"note": "shares the player\'s"}, **TALL)\n    merged, drift = laser_tag._run_scenario(\n        {}, {"repositories": {"deli_counter": str(dc)}})\n    assert merged["player_eye_height_m"] == 1.85\n    assert merged["enemy_eye_height_m"] == 1.85\n    assert any(line.startswith("enemy_eye_height_m:") for line in drift), drift\n    project = _staged(tmp_path / "proj")\n    laser_tag._write_scenario(project, merged)\n    tres = (project / "mission_scenario.tres").read_text(encoding="utf-8")\n    assert "player_eye_height_m = 1.85" in tres\n    assert "enemy_eye_height_m = 1.85" in tres\n    run = laser_tag._run_engagement(lasertag_contract.MEASURED, merged)\n    assert (run.crew_eye, run.enemy_eye) == (1.85, 1.85)\n    assert abs(run.cover_break_height - (1.85 + 1.15) / 2.0) < 1e-9\n\n\ndef test_a_contract_with_no_npc_block_shares_the_player_s_eye(tmp_path):\n    body = agent_contract.read_player_body(_contract(tmp_path, **TALL))\n    assert body["enemy_eye_height_m"] == body["player_eye_height_m"] == 1.85\n\n\ndef test_a_distinct_class_states_its_own_eye(tmp_path):\n    """An NPC block stating an eye is a distinct class, and the eye is its own.\n    The run then has two, which the advisory says (`LT_SIGHT_ONE_EYE`)."""\n    body = agent_contract.read_player_body(\n        _contract(tmp_path, npc={"eye_height_m": 1.7}, **TALL))\n    assert body["player_eye_height_m"] == 1.85\n    assert body["enemy_eye_height_m"] == 1.7\n\n\ndef test_a_nonsense_npc_eye_is_dropped_rather_than_replaced(tmp_path):\n    """What the NPC states is its own, so a nonsense eye is dropped -- the run\n    keeps Laser Tag\'s -- rather than quietly swapped for the player\'s."""\n    body = agent_contract.read_player_body(\n        _contract(tmp_path, npc={"eye_height_m": "tall"}, **TALL))\n    assert "enemy_eye_height_m" not in body\n    assert body["player_eye_height_m"] == 1.85\n\n\ndef test_a_brief_s_scenario_still_beats_the_contract(tmp_path):\n    """Precedence is stock <- contract <- this job\'s scenario, for the enemy\'s\n    eye as for the player\'s."""\n    dc = _contract(tmp_path / "dc", **TALL)\n    merged, _ = laser_tag._run_scenario(\n        {"scenario": {"enemy_eye_height_m": 1.6}},\n        {"repositories": {"deli_counter": str(dc)}})\n    assert merged["enemy_eye_height_m"] == 1.6\n    assert merged["player_eye_height_m"] == 1.85\n\n\ndef test_the_shipped_contract_fields_one_eye_on_both_sides():\n    """The Deli Counter beside this checkout, not a fixture: its NPC states no\n    eye of its own, so a run fields one eye on both sides. Skipped when the\n    sibling checkout is absent."""\n    dc = sibling_repo("deli_counter", marker="agent_contract.json")\n    if dc is None:\n        pytest.skip(not_found("deli_counter", marker="agent_contract.json"))\n    body = agent_contract.read_player_body(dc)\n    assert body["enemy_eye_height_m"] == body["player_eye_height_m"]\n'}
CHANGELOG = "## [0.231.0] - the enemy sights from the contract's body too\n\n**The factory's roadmap 292.** `adapters/laser_tag` writes the contract's body into every run's scenario (roadmap\n123), and wrote only the player's: `enemy_eye_height_m` went out at `_STOCK_SCENARIO`'s 1.6 whatever\n`deli_counter/agent_contract.json` said. The contract says its NPCs share the player's metrics until a distinct class\nships, and Laser Tag has built every enemy's capsule, mesh and agent from the crew's body in the scenario since its\n0.26.0 -- so a studio stating a 2.05 m character with a 1.85 m eye fielded 2.05 m enemies sighting from 1.6 m, and the\nevaluator's lines crossed at 1.42 m where the body's own cross at 1.5. 0.230.0's `LT_SIGHT_ONE_EYE` said so for every\nsuch contract.\n\n### Changed\n- **The enemy's eye crosses the seam.** `agent_contract.read_player_body` reads the enemy's eye too (`_NPC_FIELDS`):\n  `characters.npc_standard`'s `eye_height_m`, and the player's where that block states none. A value the NPC states is\n  its own, so a nonsense one is dropped -- the run keeps Laser Tag's -- rather than replaced with the player's.\n  `_run_scenario`'s precedence is unchanged: stock <- contract <- this job's scenario. The eye alone: Laser Tag builds\n  an enemy's body from the crew's radius and height, and has no enemy radius or height to write.\n- **`_metres`**, the one test of a value the reader writes -- a positive number, never a bool -- asked by both loops.\n\n### Measured, kept\n- **One stated body is one eye on both sides.** The shipped contract's NPC states no eye of its own, so a stock run\n  writes the 1.6 m on both sides it wrote before, and `LT_SIGHT_ONE_EYE` speaks now only for a contract stating a\n  distinct NPC eye, or a brief moving one side.\n- REFUTED, kept in the factory's roadmap 292: that the enemy's body size follows nothing. Laser Tag 0.26.0 (the\n  factory's roadmap 197) builds every enemy from the scenario's `player_radius_m` and `player_height_m`, which this\n  seam writes from the contract (Laser Tag's `test_enemy_is_the_contracts.gd`, its check [2]).\n\n### Tests\n- **test_the_enemy_sights_from_the_contract.py** (new, 6): one stated body, and both sides sight from it -- in the\n  scenario `run` writes and in the engagement the advisory is given, the evaluator's lines crossing where the body's\n  own do; a contract with no NPC block shares the player's eye; a distinct class states its own; a nonsense NPC eye is\n  dropped rather than replaced; a brief's scenario still beats the contract; the shipped contract fields one eye on\n  both sides. On 0.230.0 four fail on behaviour, the reader giving no enemy eye, and the two guards pass (the\n  factory's `patches/lf_enemy_eye/prove_tests_on_0230.out.txt`).\n- **test_sight_follows_the_body.py**: a stated body draws no `LT_SIGHT_ONE_EYE`, and the run's precedence puts the\n  enemy's eye at the body's 1.85 m -- both failing on 0.230.0 on behaviour; the two-eyes test states a distinct NPC\n  eye, since one body no longer gives two.\n\n"
OLD_VERSION, NEW_VERSION = '0.230.0', '0.231.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (LF / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: level_factory/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: level_factory/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: level_factory/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (LF / name).exists():
            raise SystemExit("REFUSED: level_factory/%s exists already; nothing written" % name)
    v = LF / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = LF / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (LF / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("Level Factory %s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in level_factory/: the "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
